$string['settings:embed_dimensions'] = '埋め込みの次元数';
$string['settings:embed_dimensions_desc'] = '埋め込みベクトルの次元数で、モデルが実際に提供している次元数でなければなりません。OpenAI text-embedding-3-small: 1536。nomic-embed-text: 768。Voyageのモデルは256、512、1024、2048を受け付けます（本来の1024はリクエストから省略されます）。無効な次元数は送信せずに省略します。送信してしまうと、指定した次元数ではなく本来の次元数が黙って返ってくることになります。2048でのvoyage-4-largeが測定済みの構成です — 現実的なクエリで再現率+14.0ポイント、月$4未満 — が、これを採用するには完全な再インデックスが必要です。リトリーバーは異なる埋め込み空間のチャンクに対してクエリを採点することを拒否するためです。この値を先に変更するのではなく、RAGインデックスのページにある埋め込みモデルの移行を使用してください。';
