// v4.4.0: course-page CSP setting.
$string['settings:csp_course_pages_mode'] = 'コースページのContent-Security-Policy';
$string['settings:csp_course_pages_mode_desc'] = 'AIコースアシスタントのウィジェットが有効なコースページに、任意でCSPヘッダーを送信します。<strong>オフ</strong>: ヘッダーを送信しません（デフォルト）。<strong>レポートのみ</strong>: <code>Content-Security-Policy-Report-Only</code>を送信します。ブラウザーは違反を記録しますがブロックはしません。1週間程度の観察期間に便利です。<strong>強制</strong>: <code>Content-Security-Policy</code>を送信します。ブラウザーは許可リスト外のiframeソース、フェッチ、その他の危険な読み込みをブロックします。サイト設定の「追加HTML」に貼り付けられた任意のスクリプトの影響を抑えるのに役立ちます（2026-04-29のIBL AI / Raisonのインシデント）。[[tutorshort]]のエンドポイントには影響しません。エンドポイントは常により厳格なCSPを送信します。';
$string['settings:csp_mode_off'] = 'オフ（コースページにヘッダーなし）';
