$string['settings:vendor_dpa_overrides'] = 'ベンダーDPAの上書き (JSON)';
$string['settings:vendor_dpa_overrides_desc'] = 'JSON object keyed by vendor id. Each value is an object whose fields override the hardcoded vendor row. Fields you do not specify fall through to the default. A new vendor key in the override is added to the table; edits apply per field. Malformed JSON is ignored at runtime — fix the parse error here when the saved value does not appear in the Vendor DPA page.';
$string['settings:rate_card_overrides'] = 'LLMレートカードの上書き (JSON)';
$string['settings:rate_card_overrides_desc'] = 'モデル名のプレフィックスをキーとするJSONオブジェクトです。各値は100万トークンあたりUSDでの<code>{"input": float, "output": float}</code>です。そのプレフィックスについて同梱のレートカードのエントリを置き換えます。例: <pre>{ "gpt-4o-mini": { "input": 0.15, "output": 0.60 }, "claude-sonnet-4.6": { "input": 3.00, "output": 15.00 } }</pre> v7.4.0からは読み取り専用です: このフィールドは引き続きマージされる（同梱のベースラインより上、モデルレジストリより下）ため既存のオーバーライドは動作し続けますが、もう何も書き込まれません。新しい価格はモデルレジストリに置いてください。レジストリは各価格を誰がいつ設定したかを記録します。週次リフレッシュは以前このフィールド全体を上書きしており、次回の実行時に手入力した価格をすべて破壊していました。';

