$string['pedagogy:talking_avatar_desc'] = '有効にすると、コースに独自の上書き設定がない限り、トーキングアバターの画面がすべてのコースで有効になります。下で設定済みのプロバイダー（D-ID、HeyGen、Tavus、または Synthesia Agents）が必要です。設定されていない場合、ウィジェットには「プロバイダーを設定してください」という通知が表示され、アバターはアニメーションしません。';
$string['settings:talking_avatar_heading'] = 'トーキングアバター';
