$string['settings:avatar_rate_card_overrides_desc'] = 'アバタープロバイダーをキーとし、1分あたりのUSD単価を1つ持つJSONオブジェクトです。そのプロバイダーについて同梱のレートを置き換えます。例: <pre>{ "did": 0.18, "heygen": 0.40, "tavus": 0.25 }</pre> 空の場合はv4.10.0で同梱されたデフォルト値を使用します: D-ID $0.30/分、HeyGen $0.50/分、Tavus $0.30/分、Synthesia $0.40/分。分析ダッシュボードに機関の実際のコストが反映されるよう、契約しているレートを設定してください。';
$string['settings:talking_avatar_did_webhook_secret'] = 'D-IDのWebhook署名シークレット';
$string['settings:talking_avatar_did_webhook_secret_desc'] = '任意です。設定すると、D-IDはセッション終了イベントを、このシークレットで<code>X-DID-Signature</code>（16進のHMAC-SHA256）として署名したうえで<code>{wwwroot}/local/ai_course_assistant/talking_avatar_webhook.php?provider=did</code>にPOSTできます。Webhookの行はフロントエンドのハートビートより優先されます。空の場合はハンドラーがオフになり、セッション終了はハートビートと毎時のスイーパーのみで処理されます。';
