$string['settings:socratic_verbose'] = 'ソクラテス式モードの詳細プロンプト';
$string['settings:socratic_verbose_desc'] = 'オンにすると、ソクラテス式モードのコースには、v3.9.30で当初追加された約600トークンの「するべきこと/してはいけないこと」の指示が全文送られます。オフ（デフォルト）の場合は、最新のホスト型モデルが確実に従える1行の指示が送られ、1ターンあたり約600トークンを節約します。明示的な足場を必要とする非力なセルフホスト型モデルでコースを運用している場合はオンにしてください。';
$string['settings:prompt_budget_chars'] = 'システムプロンプトの文字数予算';
$string['settings:prompt_budget_chars_desc'] = 'Maximum total size of the assembled system prompt before the user message, in characters. The structured prompt builder organises sections by category (identity, course context, learner state, behaviour, markers, safety) and drops or truncates the lowest-priority sections when the budget is exceeded. Safety guidance is always preserved in full. Default 8,000 characters (~2,000 tokens). Lower values reduce per-turn cost; higher values allow more course content to land in-prompt.';
$string['settings:current_page_content_maxchars'] = '現在ページのコンテンツ上限（文字数）';
$string['settings:current_page_content_maxchars_desc'] = 'RAGがオフのときに、システムプロンプトの「Current Page Content」セクションとして挿入される現在ページのテキストの最大文字数です。デフォルトの8,000は、構造と指示のための予算を残しつつ、ページ固有の質問を十分に裏付けます。（RAGが有効な場合、ページは代わりに現在ページを優先した最も関連性の高い独自のチャンクで裏付けられるため、この上限は適用されません。）非常に長いページは先頭からこの文字数まで切り詰められるため、極端に長いページの末尾は引用されない可能性があります。RAGを有効にするとこれを回避できます。コストを意識するサイトはより低く制限できます（例：3,000-4,000）。範囲は500-8,000に制限されます。<code>prompt_budget_chars</code>とは独立しています：これはページセクションのみを制限し、予算はプロンプト全体を制限します。';
$string['settings:prompt_verbosity'] = 'プロンプトの詳細度';
$string['settings:prompt_verbosity_desc'] = '指示ブロック（ソクラテス式モード、外部リソース）のデフォルトの詳細度です。簡潔（デフォルト）は最新のホスト型モデルが確実に従えるレベルです。標準は中位のモデル向けに明示的な足場を追加します。詳細は、非力なセルフホスト型モデル向けにv3.9.30当時の重厚なガイダンスをそのまま維持します。<code>prompt_verbosity_course_&lt;id&gt;</code>でコースごとに上書きできます。';
$string['settings:prompt_verbosity_concise'] = '簡潔（ホスト型モデルに推奨）';
$string['settings:prompt_verbosity_standard'] = '標準';
$string['settings:prompt_verbosity_verbose'] = '詳細（非力なセルフホスト型モデル向け）';
$string['settings:prompt_metrics_enabled'] = 'セクションごとのプロンプト指標を記録する';
$string['settings:prompt_metrics_enabled_desc'] = 'オン（デフォルト）の場合、チャットのやり取りごとに、組み立てられたプロンプト1件につき1行のJSONを<code>moodledata/sola_prompt_metrics/YYYY-MM-DD.log</code>に書き出し、カテゴリー別の文字数を記録します。直近7日分が保持されます。指標の管理ページはこれらを集計して予算の推奨値を算出します。個人を特定できる情報は記録されず、記録されるのはセクションのサイズのみです。指標ファイルを一切残したくない機関はオフにしてください。';
$string['settings:prompt_budget_auto_tune'] = 'システムプロンプト予算の毎日の自動調整（非推奨）';
$string['settings:prompt_budget_auto_tune_desc'] = '非推奨です。上の予算モードが<strong>固定</strong>に設定されていない限り、何も行いません。以前は毎日のタスクが、切り詰めを監視してそれまでに見た最大のプロンプトを追いかけることで文字数予算を推定していました。モデルのコンテキストウィンドウから予算を導出するほうが優れています。振動せず、助走用のデータも要りません。さらに両者は衝突していました。このタスクが文字数予算を書き込み、既定値以外の値は導出された予算を無効にするからです。オフのままにしてください。将来のリリースで削除されます。推奨値は引き続き<a href="/local/ai_course_assistant/prompt_metrics.php">プロンプト指標</a>ページに表示されます。';
