// v5.3.0: Empathetic communications + carryover memory (English fallback).
$string['task:milestone_check'] = '日次のマイルストーン振り返りメールを送信する（v5.3.0）';
$string['task:struggle_signal_review'] = 'つまずきシグナルを確認し、非公開の学習者メモリーに反映する（v5.3.0）';
$string['empathy:title'] = '共感的なコミュニケーションと持ち越しメモリ (v5.3.0)';
$string['empathy:desc'] = '[[tutorshort]] を、耳を傾けてくれるコーチにより近づける3つの連携機能です。目標は、学習者がここにいる理由を捉えます。持ち越しメモリは、これまで何が難しかったかを記憶し、[[tutorshort]] が別の角度から提示できるようにします。マイルストーンは、連続学習日数とコース修了をメールで称えます。各機能には独立したキルスイッチと学習者のオプトインがあります。つまずきのシグナルがチャットの外に出ることはありません — 難しかったセッションについてメールが送られることは一切ありません。';
$string['empathy:outreach_master_enabled'] = 'アウトリーチのマスターキルスイッチ';
$string['empathy:outreach_master_enabled_desc'] = '新規インストールではデフォルトでオフです。オフの場合、下の機能別スイッチにかかわらず、共感的なメールはいかなる種類も一切送信されません。機能別のデフォルトと学習者ごとの同意フローを確認したうえで、これをオンにしてください。';
$string['empathy:goals_enabled'] = 'キャリア目標の会話を有効にする';
