// v5.10.x strings (token-aware budgeting, backend retry, self-test, deployment presets, escalation consent, privacy).
$string['settings:backend_context_tokens'] = 'バックエンドのコンテキストウィンドウ（トークン）';
$string['settings:backend_context_tokens_desc'] = 'AIバックエンドの最大コンテキスト長（max_model_len）をトークン単位で指定します。大きなウィンドウを持つホスト型モデルの場合は0に設定してください（クランプなし）。0より大きい値（例えばセルフホストのvLLMバックエンドで8192）に設定すると、SOLAは上記のシステムプロンプトの文字バジェットを縮小し、トークン密度の高い言語でもプロンプト、予約された出力、会話履歴がウィンドウに収まるようにします。これが同時利用ユーザー数にどう対応するかについては、Deployment Sizingウィキページを参照してください。';
$string['settings:backend_retry_attempts'] = 'バックエンドの再試行回数';
$string['settings:backend_retry_attempts_desc'] = '学生にエラーを表示する前に、一時的なバックエンドエラー（HTTP 429または503）を再試行する回数です。再試行は応答テキストがストリーミングされる前にのみ行われるため、出力が重複することはありません。負荷時にリクエストを拒否する小規模なセルフホストバックエンドを想定しています。無効にするには0に設定します。デフォルトは2です。';
$string['settings:backend_retry_max_wait'] = 'バックエンド再試行の最大待機時間（秒）';
$string['settings:backend_retry_max_wait_desc'] = '再試行する前に、バックエンドからのRetry-Afterヘッダーをどれだけ長く尊重するかの上限を秒単位で指定します。バックエンドがRetry-Afterを送信しない場合、SOLAは代わりに短い指数バックオフを使用します。デフォルトは5です。';
$string['prompt:truncation_hint'] = '注意：長さの制限により、このターンではコース内容全体を検索できませんでした。提供された内容の中に見つけられないことを学生が尋ねた場合は、コース全体を検索できなかったと伝え、コースに存在しないと述べるのではなく、その話題が扱われている特定のページやアクティビティを開くよう提案してください。';
