$string['settings:escalation_intent_patterns'] = 'エスカレーション意図のパターン';
$string['settings:escalation_intent_patterns_desc'] = 'PCRE, no delimiters. 1行に1つの正規表現を記述します。# で始まる行は無視されます。サポートチケットが作成されるのは、学習者自身のメッセージがいずれかのパターンに一致した場合のみです。そのため、コース教材が学習者に代わってエスカレーションを引き起こすことはありません。空欄のままにすると組み込みの既定値が使われ、英語に加えてスペイン語・フランス語・ドイツ語・ポルトガル語の一般的な言い回しに対応します。学習者が他の言語で書くサイトでは、ここにパターンを追加してください。一致しないメッセージではチケットは作成されません。';
$string['settings:zendesk_require_consent'] = 'サポートエスカレーション前に同意を必須にする';
$string['settings:zendesk_require_consent_desc'] = '有効（推奨）の場合、SOLAは学習者が初回起動時の同意通知を承諾した後にのみ会話をZendeskサポートデスクにエスカレーションします。この通知は、人間の支援を求めると会話（名前とメールアドレスを含む）がサポートと共有されることを開示します。その同意を他の方法で取得する場合にのみオフにしてください。オフの場合、エスカレーションは即座に送信されます。Zendeskエスカレーションが有効になっていない限り効果はありません。';
