$string['settings:rag_min_similarity'] = '最小関連度（コサイン）';
$string['settings:rag_min_similarity_desc'] = '質問とのコサイン類似度がこの値を下回る取得チャンクを除外します。これにより、トピックから外れた、または情報の乏しい質問が、常に弱い一致でTop-Kまで埋めるのではなく、より少ない（またはゼロの）パッセージを挿入するようになります。範囲は0から1。0でこのゲートを無効にします。適切な値は埋め込みモデルに依存します。0.25はtext-embedding-3-smallに適しています。値を上げるとより厳格になり（コンテキストは少なくなるがトピックにより適合）、下げるとより寛容になります。';
$string['settings:rag_currentpage_boost'] = '現在ページのブースト';
$string['settings:rag_currentpage_boost_desc'] = '学習者が現在閲覧しているページのチャンクの関連度スコアに加算される小さなボーナスです。これにより、「これを説明して」のような質問は、スコアが近い場合に表示中のページを優先します。順序付けのみ：無関係なページチャンクを最小関連度ゲートを越えて強制することはありません。0に設定すると無効になります。';
$string['settings:history_mode'] = '履歴選択モード';
$string['settings:history_mode_desc'] = '過去の会話ターンがモデルに送信される前にどのように選択されるかを指定します。<strong>セマンティック</strong>は、現在の質問に関連する最近のターンのみ（および常に最新のやり取り）を保持するため、古くてトピックから外れた以前のターンがコストを膨らませたり回答を脱線させたりしません。メッセージごとに1回の追加の埋め込み呼び出しが発生します。<strong>新しさ順</strong>は、関連性に関係なく最後の「Max Conversation History」ペアを保持します（従来の動作、追加の呼び出しなし）。埋め込みが利用できない場合、セマンティックモードは自動的に新しさ順にフォールバックします。';
$string['settings:history_mode_semantic'] = 'セマンティック（関連する最近のターン）';
$string['settings:history_mode_recency'] = '新しさ順（最後のN組）';
$string['settings:history_semantic_minscore'] = '履歴関連度の下限（コサイン）';
$string['settings:history_semantic_minscore_desc'] = 'セマンティック履歴モードでは、過去のターンは現在の質問との類似度が少なくともこの値以上の場合にのみ保持されます（最新のやり取りは常に保持されます）。範囲は0から1。モデルに依存します。値を上げるとより厳格になり（履歴が少なくなる）、下げるとより多く保持されます。';
$string['settings:history_candidates'] = '履歴候補ウィンドウ';
$string['settings:history_candidates_desc'] = 'セマンティック履歴モードでは、最新のこの数のペアのみが関連性のスコアリング対象になります（コスト制限）。このウィンドウより古いペアは送信されません。この値は「Max Conversation History」以上に保ってください。';

// v5.11.0 - v6.2.0 strings (added 2026-06-10).
