$string['settings:rerank_enabled_desc'] = '有効にすると、RAG取得が二段階になります: コサイン類似度が上位N候補を返し（デフォルト50）、Voyage rerank-2.5クロスエンコーダーが各候補にスコアを付けて上位KがプロンプトへIn。公表されたリフト: エンタープライズRecall@10が+15、BEIR NDCGが+39%。~$0.05/MTokの課金。以下の<code>rerank_apikey</code>が必要で、リランクが失敗または未設定の場合は単一ステージのコサインにグレースフルフォールバックします。';
