$string['settings:prompt_proportions_heading_desc'] = 'システムプロンプトのバジェットを4つのバケットに配分します: 安全性・アイデンティティ、コース構造、コースコンテンツ、現在のページ。ウェイトは合計100になるパーセンテージです。経験的に調整されたデフォルト（10 / 10 / 40 / 40）はv5.6.0のウェイト調整ベンチマークから来ています。テキストエリアを空白にするとそのデフォルトが使用されます。自動ブーストは特定のページがコンテキスト内にあるかどうかに応じてターンごとに配分を調整します。';
$string['settings:prompt_section_weights'] = 'ベースセクションウェイト（JSON）';
$string['settings:prompt_section_weights_desc'] = '各バケットをパーセンテージにマップするオプションのJSONオブジェクト。空白のままにするとベンチマーク済みデフォルト（10 / 10 / 40 / 40）を使用します。例: <code>{"safety_identity": 10, "course_structure": 10, "course_content": 40, "current_page": 40}</code>。ウェイトの合計は100（±5%）でなければなりません。<code>safety_identity</code>はジェイルブレイク対策と出力フォーマットマーカーが常に完全に含まれるように最低10%の下限があります。<code>current_page + course_content</code>はモデルが根拠となる実質的な材料を持てるように少なくとも40%でなければなりません。範囲外の値はベンチマーク済みデフォルトに暗黙的にフォールバックします。管理者は保存後にプロンプトデバッグログを確認して検証することをお勧めします。';
$string['settings:prompt_context_boost_mode'] = 'コンテキストブーストモード';
$string['settings:prompt_context_boost_mode_desc'] = '特定のページがコンテキスト内にある場合は現在ページセクションへ、ページが選択されていない場合はコースコンテンツへウェイトをシフトする自動調整。<strong>page_focus</strong>（デフォルト）は約15ウェイトポイントシフトします。<strong>aggressive</strong>は25ポイントシフトし、学習者が常にページ固有の質問をする場合に最適です。<strong>off</strong>はブーストを無効にし、管理者が設定したベースウェイトがページコンテキストに関係なくすべてのターンに適用されます。';
$string['settings:prompt_context_boost_off'] = 'オフ（すべてのターンでベースウェイトを使用）';
$string['settings:prompt_context_boost_page_focus'] = 'ページフォーカス（デフォルト、~15ポイントシフト）';
$string['settings:prompt_context_boost_aggressive'] = 'アグレッシブ（~25ポイントシフト）';
$string['settings:prompt_section_weights_coach'] = 'コーチモードオーバーライド（JSON、省略可能）';
