$string['settings:mastery_classifier_provider_desc'] = 'ターンごとのマスタリークラシファイアーに使用するプロバイダーID。空白のままにするとデフォルトAIプロバイダーを継承します。デフォルトの<code>openai</code>は以下の<code>gpt-4o-mini</code>クラシファイアーモデルと組み合わせます — 構造化出力分類のための最も安価なTIER 1オプション（チャット層との比較で100k MAU時に年約$220節約）。設定時は、このプロバイダーIDを持つ比較プロバイダーの行がAPIキー、ベースURL、温度を提供します。';
