$string['settings:premium_escalation_triggers'] = 'プレミアムトリガーregex';
$string['settings:premium_escalation_triggers_desc'] = '1行に1つのPCRE regex（区切り文字なし。大文字小文字を区別しないマッチングが自動的に適用されます）。#で始まる行はコメントです。空白のままにするとA.10ベイクオフからのキュレーション済みデフォルトセット（複数ステップSTEMマーカー: "derive"、"prove that"、"step by step"、LaTeX数学、フェンスされたコードブロック、big-O、積分、最適化など）を使用します。';
