$string['settings:cost_anomaly_heading'] = 'コスト異常検出器（v6.0）';
$string['settings:cost_anomaly_heading_desc'] = '今日のサイト全体のSOLA支出と7日間のローリング中央値を比較する日次スケジュールタスク（<code>cost_anomaly_check</code>）。今日が設定された乗数×中央値を超えると<code>spend_notify_emails</code>受信者リスト（サイト管理者にフォールバック）にメールを送信します。既存の80% / 95% / 100%の支出上限閾値が見逃す3つの障害モードを検出します: (1) 絶対上限は超えないが単一コースが突然通常の10倍のボリュームを出す暴走コース、(2) 誤ってプレミアム層を有効化、(3) プロバイダーの誤ルーティング。デフォルトはオフ。<code>.drafts/sola-redash-cost-anomaly-2026-06-09.md</code>のRedashクエリに相当するSOLA内機能。';
$string['settings:cost_anomaly_enabled'] = 'コスト異常検出器を有効にする';
$string['settings:cost_anomaly_enabled_desc'] = 'オンにすると、日次スケジュールタスクが今日の支出を7日間のローリング中央値と比較し、異常時に管理者にメールを送信します。有効化後の最初の7日間は<code>insufficient_history</code>ステータス（まだ履歴ベースラインがない）が生成され、アラートは発行されません。1日あたり冪等: <code>config_plugins</code>のフラグがcronが複数回実行された場合の繰り返しメールを防ぎます。';
$string['settings:cost_anomaly_multiplier'] = '異常乗数';
$string['settings:cost_anomaly_multiplier_desc'] = 'アラートをトリガーするには今日の支出がこの乗数×7日間中央値を超える必要があります。デフォルト <code>2.0</code>。早期警告のために<code>1.5</code>に下げます（入学バースト中の偽陽性が増えます）。Saylorの使用量が2倍スパイクが日常的になるほど不安定な場合は<code>3.0</code>に上げます。';
$string['settings:prompt_debug_enabled'] = '組み立てられたシステムプロンプトをファイルに記録する';
$string['settings:prompt_debug_enabled_desc'] = 'オンにすると、すべてのチャットターンで完全に組み立てられたシステムプロンプトとセクションごとの文字数を<code>moodledata/temp/sola_prompt_debug.log</code>（~1MBでローリング）に書き込みます。デフォルトはオフ。プロンプトサイズを経験的に測定し、どのセクションが最も多くのトークンに貢献しているかを監査するために使用します。ログにはシステムプロンプトのみが含まれます（学習者の入力やPIIはありません）。';
