$string['settings:failover_per_call_enabled'] = '呼び出し単位のフェイルオーバー（v5.5.0）';
$string['settings:failover_per_call_enabled_desc'] = '有効にすると、すべてのチャット呼び出しでプライマリのプロバイダがフェイルオーバーチェーンのデコレータで包まれます。呼び出しのタイムアウトまたは 5xx エラーが発生すると、[[tutorshort]] は上記の<strong>フェイルオーバーチェーン</strong>の次のエントリに切り替え、失敗したプロバイダに対して15分間のサーキットを開きます。切り替えのたびに監査行（<code>failover_fallthrough</code>）が記録されます。有効化後は 管理 -> [[tutorshort]] -> 監査ログ を確認し、チェーンが正常であることを確かめてください。既定では無効です。チェーンの検証が済み、チェーン上のすべてのプロバイダについて必要なデータ処理条件が整っていることを所属機関が確認してから有効にしてください。';
$string['settings:failover_timeout_chat'] = '呼び出し単位のフェイルオーバー：チャットのタイムアウト（秒）';
$string['settings:failover_timeout_chat_desc'] = '切り替えるまでに、チャットプロバイダからの最初のトークンを待つ時間です。既定は8秒です。値を小さくすると応答の遅いプロバイダからの切り替えが速くなりますが、一時的に遅いだけのリクエストで誤って切り替わりやすくなります。値を大きくするとプライマリのプロバイダに留まる時間が長くなります。<strong>呼び出し単位のフェイルオーバー</strong>が有効な場合にのみ参照されます。';
$string['settings:spend_notify_emails'] = '支出アラートの送信先';
