$string['settings:voice_providers_heading'] = '音声プロバイダ（Realtime、TTS、STT）';
$string['settings:voice_providers_heading_desc'] = '1つ以上の音声 API プロバイダを設定します。これらの設定は上のチャットプロバイダおよび RAG の埋め込みプロバイダとは独立しています。現時点で WebSocket による Realtime、TTS、STT のエンドポイントを提供しているのは OpenAI と xAI のみであるため、音声には専用のプロバイダ一覧があります。下のドロップダウンで、登録済みのどのプロバイダが各機能を担当するかを選択してください。行が1つも定義されていない場合は、従来の単一キー方式（上の Realtime API キー、またはプライマリの OpenAI キー）が使用されます。チャットに Together AI / Anthropic / DeepSeek / Gemini / Mistral を使用しているサイトでは、音声を動作させるために少なくとも1行をここで設定する必要があります。';
