$string['settings:voice_active_stt'] = '有効な STT プロバイダ';
$string['settings:voice_active_stt_desc'] = '学習者の音声をテキストに変換する処理をどのプロバイダが担当するかを指定します。空欄にすると、下でセルフホストの Whisper サーバが設定されている場合はそれを優先し、次に音声プロバイダの先頭行、さらに従来のキーの順にフォールバックします。';
$string['settings:stt_selfhosted_enabled'] = 'セルフホストの文字起こしを有効にする';
$string['settings:stt_selfhosted_enabled_desc'] = '下のセルフホスト Whisper サーバを、音声入力と Soapbox の音声認識経路として使用します。下でサーバの URL の指定が必要です。無効の場合は、URL が設定されていても、文字起こしはホスト型（OpenAI Whisper）またはブラウザ内の経路にフォールバックします。';
