$string['settings:customavatars_desc'] = '正方形の PNG または SVG 画像をここにアップロードすると、上のアバター選択リストに追加されます。アップロードした各ファイルは選択可能な既定項目（接頭辞 "Custom:"）になります。このリストからファイルを削除すると、選択リストからも削除されます。ヒント：256×256 の PNG は Retina ディスプレイに適しています。';
$string['settings:anomaly_digest_heading'] = 'Learning Radar — 異常検知ダイジェスト';
$string['settings:anomaly_digest_heading_desc'] = '低評価、トークン支出、学術的誠実性のフラグについて、移動窓を比較する日次チェックです。いずれかの指標が設定したしきい値を超えると、設定済みのチャネルにダイジェストが送信されます。クエリ単位の定期レポートについては、[[tutorshort]] 分析ページのスケジュールパネルをご利用ください。';
