$string['privacynotice:collects_p2'] = '[[tutorshort]]は、サービスの運用に必要な標準的な技術データも収集します。Moodleのユーザーid、IPアドレス、ブラウザの種類、タイムスタンプです。[[tutorshort]]は、氏名、メールアドレス(メール配信を拒否した場合は、その拒否が適用されるアドレスを保存します)、住所、電話番号(リマインダー用に提供した場合を除く)、支払い情報、政府発行の識別番号について、独自の記録を保持しません。[[tutorshort]]のデータの隣にあなたの名前が表示される場合、それは既存の[[uniname]]アカウントから読み取られたもので、[[tutorshort]]が保存しているものではありません。';
