$string['settings:embed_input_type_asymmetric'] = '非対称 クエリ/文書（推奨）';
$string['settings:embed_input_type_mode'] = '埋め込み入力タイプ';
$string['settings:embed_input_type_mode_desc'] = 'Voyage の埋め込み専用です。Voyage はクエリか文書かによってテキストの射影を変えます。「非対称」は検索時に input_type=query、インデックス作成時に input_type=document を送ります。これがベンダーの意図であり、このコーパスで最も良い測定結果が出る設定です。クエリ側に文書の射影を使うと再現率が 30.8 ポイント低下し、クエリ長のすべての区分で負けました（2026-08-21、voyage-3.5、本番相当のセット）。「共有空間」は両側に input_type=document を送ります。検索性能は明確に劣り、移行時の保険としてのみ存在します。射影が 1 つなら、コーパスを再埋め込みせずにクエリ用モデルを変更できるからです。移行の途中でない限り非対称を選んでください。この変更に再インデックスは不要で、変わるのはクエリ側の射影だけです。これはモデルの非対称ペアリング（クエリに使うより大きな Voyage モデルでインデックスすること）ではありません。そちらはこのコーパスで 2 度再現できなかった別の手法で、この設定ではなくクエリ用モデルの設定が制御します。';
$string['settings:embed_input_type_shared'] = '共有空間（移行時の保険。検索性能は劣る）';
$string['settings:embed_migration_heading'] = '埋め込みモデルの移行';
$string['settings:embed_migration_heading_desc'] = '埋め込みモデルまたはその次元数を変更すると、保存済みのベクトルはすべて無効になります。リトリーバーは異なる埋め込み空間のチャンクに対してクエリを採点することを拒否するため、コースは不正確な取得をするのではなく、まったく何も取得しなくなります。これらの設定は移行「先」のモデルを指定するものです。その後、コースはRAGインデックスのページから1つずつ再埋め込みされ、新しいベクトルは古いものと並べて書き込まれます。上のライブ設定は、ご自身で変更するまで取得の処理を続けます。';
