$string['settings:anomaly_digest_floor_usd'] = '異常ダイジェスト: アラートを出す最小支出額（USD）';
$string['settings:anomaly_digest_floor_usd_desc'] = '直近24時間のコストがこの額を下回る場合は、上昇率がどれほど大きくてもトークン支出アラートを抑制します。母数が小さいときのパーセンテージはノイズです。1ドルから2ドルへの倍増はどんなしきい値も超えますが、何の意味もありません。実際に夜中に起こされてもよいと思える日次の金額を設定してください。0にすると下限が無効になり、上昇率のみでアラートを出します。対象期間の支出にレートカードの項目がないモデルが含まれている場合は価格を算出できないため、その場合はアラートを必ず送信します。認識できないモデルが混ざっていること自体、確認する価値があるからです。';
