$string['settings:radar_batch_heading'] = 'Learning Radar: オフラインバッチ階層';
$string['settings:radar_batch_heading_desc'] = 'スケジュールされた Learning Radar のレポートは、AIプロバイダーのオフラインバッチ階層に送信できます。この階層は入力トークンと出力トークンの両方が50%安くなる代わりに、処理に最大24時間かかります。対象となるのはスケジュールされたレポートのみです。このページから実行するアドホックな Learning Radar は回答をブラウザーにストリーミングするため常に同期処理であり、学習者向けの機能もすべて同様です。バッチの支出は <code>batch/</code> を先頭に付けたモデル名で記録されるため、AI支出ダッシュボードには定価ではなく割引後の料金が表示されます。';
$string['settings:soapbox_deprecated_inuse'] = 'Soapbox は非推奨です。後継となるのは PresenterAI で、Soapbox のすべての機能を備えた独立したMoodle活動プラグインです。活動選択画面に表示され、保存先はS3バケットとMoodle自身のファイルストレージから、AIはMoodleコアAIと、直接設定するClaude・OpenAI・Geminiから選べます。今回のリリースでは何も変わりません。課題、録音、文字起こし、スコア、フィードバックはそのままで、保持期間の設定もこれまでどおり適用され、日次のクリーンアップタスクも引き続き実行されます。コードの削除は v8.0.0 に予定されており、PresenterAI が既存の録音とスコアをインポートできるようになるまで、どのリリースでも削除されることはありません。データベーステーブルの削除は別途、さらに後になります。Soapbox は評定表に何も書き込まないため、これらのテーブルが学習者のプレゼンテーション記録の唯一の控えだからです。対応方法: 今後は Soapbox を前提にした新しいコースの構築をやめ、PresenterAI がリリースされたら併せてインストールして新規の作業にはそちらを使い、既存の Soapbox のコースはインポートが利用できるようになるまでそのまま運用してください。学習者にはまだ何も伝える必要はありません。';
$string['settings:soapbox_deprecated_off'] = 'Soapbox は非推奨であり、このサイトではどこでも有効になっていません。オフのままにしてください。後継となるのは PresenterAI で、同じ役割を果たしつつ保存先とAIプロバイダーを選べる独立したMoodle活動プラグインです。コードの削除は v8.0.0 に予定されています。';
