$string['pricedrift:eol_horizon'] = 'サポート終了の警告期間（日）';
$string['pricedrift:eol_horizon_desc'] = '公表されたモデルの提供終了を何日前から報告し始めるかを指定します。ドリフトチェックが監視するのは価格です。これがなければライフサイクルを監視するものが何もなく、実際の提供終了は警告としてではなく本番障害として現れます。モデルは停止する直前まで動作し、課金され続け、そのあと一斉にすべての呼び出しが失敗します。既定値は60日です。本番モデルの入れ替えは、比較検証と設定変更とデプロイであり、午後のひとときで終わる作業ではないからです。すでに期日を過ぎた提供終了は、この設定値にかかわらず常に報告されます。';
$string['pricedrift:eol_surfaces'] = 'このサイトが呼び出すAPIサーフェス';
$string['pricedrift:eol_surfaces_desc'] = 'カンマ区切りで指定します。例: <code>gemini-developer-api,openai-api</code>。公表された提供終了は、これらのサーフェスのいずれかについて公表された場合にのみ通知されます。それ以外も表示はされますが、自サイトの対象外として明示されます。記録されたすべてのサポート終了について通知するには空欄にしてください。この設定は実際のヒヤリハットから生まれました。gemini-2.5-flashが2026-10-16に提供終了と報告されましたが、それはVertex AIのライフサイクルの話であり、本プラグインが呼び出すGemini Developer APIには当てはまりませんでした。実害のない事象で一度でも呼び出されると、人は次の通知を無視するようになります。';
